from copy import deepcopy
import hashlib
import hmac

import psycopg
from psycopg import sql
from django.conf import settings
from django.core.management import call_command
from django.db import connections


class GymDatabaseUnavailable(Exception):
    pass


def register_database(gym):
    # Database identities are generated by the platform, never from request input.
    name = f"gym_{gym.database_key.hex}"
    password = hmac.new(
        settings.GYM_DATABASE_SECRET.encode(), name.encode(), hashlib.sha256
    ).hexdigest()
    if name not in connections.databases:
        config = deepcopy(connections.databases["default"])
        config.update(NAME=name, USER=name, PASSWORD=password)
        connections.databases[name] = config
    return name, name


def create_database(name, user, password, *, require_existing=False):
    """Privileged control-plane operation; database/role identifiers are quoted."""
    with psycopg.connect(**settings.GYM_PROVISIONER, autocommit=True) as admin:
        # Serialize retries/concurrent workers for this database without a global lock.
        admin.execute("SELECT pg_advisory_lock(hashtextextended(%s, 0))", (name,))
        try:
            row = admin.execute(
                "SELECT pg_get_userbyid(datdba) FROM pg_database WHERE datname = %s", (name,)
            ).fetchone()
            if require_existing and not row:
                raise GymDatabaseUnavailable("Restore the missing gym database before migrating")
            if row and row[0] != user:
                raise GymDatabaseUnavailable("Database owner does not match its registered gym")
            role = admin.execute("SELECT 1 FROM pg_roles WHERE rolname = %s", (user,)).fetchone()
            if not role:
                admin.execute(sql.SQL("CREATE ROLE {} LOGIN PASSWORD {}").format(
                    sql.Identifier(user), sql.Literal(password)
                ))
            if not row:
                admin.execute(sql.SQL("CREATE DATABASE {} OWNER {}").format(
                    sql.Identifier(name), sql.Identifier(user)
                ))
            admin.execute(sql.SQL("REVOKE ALL ON DATABASE {} FROM PUBLIC").format(sql.Identifier(name)))
        finally:
            admin.execute("SELECT pg_advisory_unlock(hashtextextended(%s, 0))", (name,))


def provision_database(gym):
    alias, name = register_database(gym)
    config = connections.databases[alias]
    create_database(name, config["USER"], config["PASSWORD"], require_existing=gym.database_ready)
    call_command("migrate", database=alias, interactive=False, verbosity=0)
    from websites.models import WebsiteSettings
    WebsiteSettings.objects.using(alias).get_or_create(pk=1, defaults={
        "display_name": gym.name,
        "primary_color": getattr(gym, "primary_color", "#245ac5"),
        "logo_url": getattr(gym, "logo_url", ""),
    })
    type(gym).objects.filter(pk=gym.pk).update(database_ready=True)
    gym.database_ready = True
    return alias


def ready_database(gym):
    if not gym.database_ready:
        raise GymDatabaseUnavailable("Gym database is not provisioned")
    alias, _ = register_database(gym)
    # The authenticated connection/query checks availability; never creates a database.
    return alias
